import { Locator, Page } from '@playwright/test';

export class BasketPage {
  readonly rows: Locator;
  readonly totalPrice: Locator;
  readonly checkoutButton: Locator;
  readonly snackBar: Locator;

  constructor(private readonly page: Page) {
    this.rows = page.locator('app-basket mat-row');
    this.totalPrice = page.locator('app-basket #price');
    this.checkoutButton = page.locator('app-basket #checkoutButton');
    this.snackBar = page.locator('.mat-mdc-snack-bar-container');
  }

  async open(): Promise<void> {
    await this.page.goto('/#/basket');
    await this.waitForLoad();
  }

  async waitForLoad(): Promise<void> {
    await this.page.waitForURL(/#\/basket/);
    await this.totalPrice.waitFor();
  }

  row(productName: string): Locator {
    return this.rows.filter({
      has: this.page.locator('mat-cell.mat-column-product', { hasText: productName }),
    });
  }

  quantity(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-quantity > span');
  }

  price(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-price');
  }

  minusButton(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-quantity button').first();
  }

  plusButton(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-quantity button').last();
  }

  trashButton(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-remove button');
  }

  /** Waits until the basket update request completes, so the next click uses fresh data. */
  async clickAndWaitForUpdate(button: Locator): Promise<void> {
    const update = this.page.waitForResponse(
      (r) => /\/api\/BasketItems\/\d+/.test(r.url()) && r.request().method() !== 'GET',
    );
    await button.click();
    await update;
  }

  async increase(productName: string): Promise<void> {
    await this.clickAndWaitForUpdate(this.plusButton(productName));
  }

  /**
   * Clicks minus. At quantity 1 the shop may send no update request,
   * so the wait for the request is short and optional.
   */
  async decrease(productName: string): Promise<void> {
    const update = this.page
      .waitForResponse((r) => /\/api\/BasketItems\/\d+/.test(r.url()) && r.request().method() !== 'GET', {
        timeout: 2_000,
      })
      .catch(() => undefined);
    await this.minusButton(productName).click();
    await update;
  }

  async remove(productName: string): Promise<void> {
    await this.clickAndWaitForUpdate(this.trashButton(productName));
  }

  async checkout(): Promise<void> {
    await this.checkoutButton.click();
    await this.page.waitForURL(/#\/address\/select/);
  }

  message(text: string | RegExp): Locator {
    return this.snackBar.filter({ hasText: text });
  }
}
import { Locator, Page } from '@playwright/test';

/** Top bar of the shop with the account menu and the basket button. */
export class NavBar {
  readonly accountButton: Locator;
  readonly basketButton: Locator;
  readonly basketCounter: Locator;
  readonly accountMenu: Locator;
  readonly loginMenuItem: Locator;
  readonly logoutMenuItem: Locator;
  readonly ordersAndPaymentMenuItem: Locator;

  constructor(private readonly page: Page) {
    this.accountButton = page.getByRole('button', { name: 'Show/hide account menu' });
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.basketCounter = this.basketButton.locator('.warn-notification');
    this.accountMenu = page.getByRole('menu').first();
    this.loginMenuItem = page.getByRole('menuitem', { name: 'Go to login page' });
    this.logoutMenuItem = page.getByRole('menuitem', { name: 'Logout' });
    this.ordersAndPaymentMenuItem = page.getByRole('menuitem', { name: 'Show Orders and Payment Menu' });
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await this.accountMenu.waitFor();
  }

  async closeMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await this.page.getByRole('menu').first().waitFor({ state: 'hidden' });
  }

  async openBasket(): Promise<void> {
    await this.basketButton.click();
    await this.page.waitForURL(/#\/basket/);
  }

  async openOrderHistory(): Promise<void> {
    await this.openOrdersAndPaymentItem('Go to order history page');
    await this.page.waitForURL(/#\/order-history/);
  }

  async openDigitalWallet(): Promise<void> {
    await this.openOrdersAndPaymentItem('Go to wallet page');
    await this.page.waitForURL(/#\/wallet$/);
  }

  private async openOrdersAndPaymentItem(name: string): Promise<void> {
    await this.openAccountMenu();
    await this.ordersAndPaymentMenuItem.click();
    await this.page.getByRole('menuitem', { name }).click();
  }
}
import { Locator, Page } from '@playwright/test';
import { ADDRESS, CARD_LAST_DIGITS } from '../support/test-data';

export class SelectAddressPage {
  readonly title: Locator;
  readonly savedAddressRow: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.title = page.getByRole('heading', { name: 'Select an address' });
    this.savedAddressRow = page.locator('app-address').getByRole('row').filter({ hasText: ADDRESS.fullName });
    this.continueButton = page.getByRole('button', { name: 'Proceed to payment selection' });
  }

  async selectSavedAddressAndContinue(): Promise<void> {
    await this.savedAddressRow.getByRole('radio').click();
    await this.continueButton.click();
    await this.page.waitForURL(/#\/delivery-method/);
  }
}

export class DeliveryMethodPage {
  readonly title: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.title = page.getByRole('heading', { name: 'Choose a delivery speed' });
    this.continueButton = page.getByRole('button', { name: 'Proceed to delivery method selection' });
  }

  option(name: string): Locator {
    return this.page.locator('app-delivery-method').getByRole('row').filter({ hasText: name });
  }

  optionPrice(name: string): Locator {
    return this.option(name).getByRole('cell').nth(2);
  }

  async selectAndContinue(name: string): Promise<void> {
    await this.option(name).getByRole('radio').click();
    await this.continueButton.click();
    await this.page.waitForURL(/#\/payment\/shop/);
  }
}

export class PaymentPage {
  readonly title: Locator;
  readonly savedCardRow: Locator;
  readonly walletBalance: Locator;
  readonly walletPayButton: Locator;
  readonly couponPanelButton: Locator;
  readonly couponInput: Locator;
  readonly redeemButton: Locator;
  readonly couponConfirmation: Locator;
  readonly couponError: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    const root = page.locator('app-payment');
    this.title = page.getByRole('heading', { name: 'My Payment Options' });
    this.savedCardRow = root.getByRole('row').filter({ hasText: `************${CARD_LAST_DIGITS}` });
    this.walletBalance = root.getByText('Wallet Balance', { exact: true }).locator('xpath=..').locator('.confirmation');
    this.walletPayButton = root.getByRole('button', { name: /^Pay / });
    this.couponPanelButton = root.getByRole('button', { name: /Add a coupon/ });
    this.couponInput = root.getByRole('textbox', { name: 'Coupon' });
    this.redeemButton = root.getByRole('button', { name: 'Redeem' });
    this.couponConfirmation = root.locator('.confirmation').filter({ hasText: /discount/i });
    this.couponError = root.locator('.error').filter({ hasText: /coupon/i });
    this.continueButton = root.getByRole('button', { name: 'Proceed to review' });
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanelButton.click();
    await this.couponInput.waitFor();
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponInput.fill(code);
    const response = this.page.waitForResponse((r) => r.url().includes('/rest/basket/') && r.url().includes('/coupon/'));
    await this.redeemButton.click();
    await response;
  }

  async selectSavedCardAndContinue(): Promise<void> {
    await this.savedCardRow.getByRole('radio').click();
    await this.continueButton.click();
    await this.page.waitForURL(/#\/order-summary/);
  }

  async payWithWallet(): Promise<void> {
    await this.walletPayButton.click();
    await this.page.waitForURL(/#\/order-summary/);
  }
}

/** Shared reader for the summary tables with the rows Items, Delivery, Promotion and Total Price. */
export type Totals = { items: Locator; delivery: Locator; promotion: Locator; total: Locator };

export class OrderSummaryPage {
  readonly basketRows: Locator;
  readonly deliveryAddress: Locator;
  readonly paymentMethod: Locator;
  readonly totals: Totals;
  readonly placeOrderButton: Locator;

  constructor(private readonly page: Page) {
    const root = page.locator('app-order-summary');
    this.basketRows = root.locator('mat-row');
    this.deliveryAddress = root.locator('mat-card').filter({ hasText: 'Delivery Address' }).last();
    this.paymentMethod = root.locator('mat-card').filter({ hasText: 'Payment Method' }).last();
    const value = (label: string) =>
      root.locator('tr').filter({ has: page.locator('td.label', { hasText: new RegExp(`^\\s*${label}\\s*$`) }) }).locator('td.price');
    this.totals = {
      items: value('Items'),
      delivery: value('Delivery'),
      promotion: value('Promotion'),
      total: value('Total Price'),
    };
    this.placeOrderButton = page.getByRole('button', { name: 'Complete your purchase' });
  }

  async waitForLoad(): Promise<void> {
    await this.page.waitForURL(/#\/order-summary/);
    await this.placeOrderButton.waitFor();
  }

  row(productName: string): Locator {
    return this.basketRows.filter({ hasText: productName });
  }

  async placeOrder(): Promise<string> {
    await this.placeOrderButton.click();
    await this.page.waitForURL(/#\/order-completion\/.+/);
    return decodeURIComponent(this.page.url().split('/order-completion/')[1]);
  }
}

export class OrderCompletionPage {
  readonly title: Locator;
  readonly totalsRow: Locator;

  constructor(private readonly page: Page) {
    const root = page.locator('app-order-completion');
    this.title = root.getByRole('heading', { name: 'Thank you for your purchase!' });
    // The row that holds the nested tables with the labels and the values of the totals.
    this.totalsRow = root.getByRole('row').filter({ hasText: /Promotion.*¤/s }).first();
  }

  productRow(productName: string): Locator {
    return this.page.locator('app-order-completion').getByRole('row').filter({ hasText: productName });
  }

  /** Reads the values of Items, Delivery, Promotion and Total Price in that order. */
  async totals(): Promise<{ items: number; delivery: number; promotion: number; total: number }> {
    const text = await this.totalsRow.innerText();
    const values = [...text.matchAll(/(\d+(?:\.\d+)?)¤/g)].map((m) => Number(m[1]));
    if (values.length !== 4) throw new Error(`Expected 4 totals, got: "${text}"`);
    const [items, delivery, promotion, total] = values;
    return { items, delivery, promotion, total };
  }
}
