import { Locator, Page } from '@playwright/test';

export class ProductListPage {
  readonly snackBar: Locator;

  constructor(private readonly page: Page) {
    this.snackBar = page.locator('.mat-mdc-snack-bar-container');
  }

  async open(): Promise<void> {
    await this.page.goto('/#/search');
    await this.page.locator('mat-card .name').first().waitFor();
  }

  productCard(name: string): Locator {
    return this.page.locator('mat-card').filter({
      has: this.page.locator('.name', { hasText: new RegExp(`^\\s*${escapeRegExp(name)}\\s*$`) }),
    });
  }

  productName(name: string): Locator {
    return this.productCard(name).locator('.name');
  }

  productPrice(name: string): Locator {
    return this.productCard(name).locator('.price');
  }

  addToBasketButton(name: string): Locator {
    return this.productCard(name).getByRole('button', { name: 'Add to Basket' });
  }

  async addToBasket(name: string): Promise<void> {
    await this.addToBasketButton(name).click();
  }

  /** Snack bar message that contains the text. */
  message(text: string | RegExp): Locator {
    return this.snackBar.filter({ hasText: text });
  }
}

export function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
import { test as base, expect } from '@playwright/test';
