  orderHistory: async ({ page }, use) => use(new OrderHistoryPage(page)),
  wallet: async ({ page }, use) => use(new WalletPage(page)),
});

export { expect };
import { APIRequestContext, expect } from '@playwright/test';
import { ADDRESS, CARD } from './test-data';

export type Session = { token: string; basketId: number };

/** REST client of the shop for test preconditions. The UI steps of the tests do not use it. */
export class ShopApi {
  private session?: Session;

  constructor(private readonly request: APIRequestContext) {}

  async register(email: string, password: string): Promise<void> {
    const response = await this.request.post('/api/Users', {
      data: {
        email,
        password,
        passwordRepeat: password,
        securityQuestion: { id: 1 },
        securityAnswer: 'test',
      },
    });
    expect(response.status(), await response.text()).toBe(201);
  }

  async login(email: string, password: string): Promise<Session> {
    const response = await this.request.post('/rest/user/login', { data: { email, password } });
    expect(response.ok(), await response.text()).toBeTruthy();
    const { authentication } = await response.json();
    this.session = { token: authentication.token, basketId: Number(authentication.bid) };
    return this.session;
  }

  async productId(name: string): Promise<number> {
    const response = await this.request.get('/api/Products');
    expect(response.ok()).toBeTruthy();
    const { data } = await response.json();
    const product = data.find((p: { name: string }) => p.name === name);
    if (!product) throw new Error(`Product not found in the catalog: ${name}`);
    return product.id;
  }

  async addToBasket(productName: string, quantity: number): Promise<void> {
    const ProductId = await this.productId(productName);
    const response = await this.request.post('/api/BasketItems', {
      headers: this.authHeaders(),
      data: { ProductId, BasketId: this.requireSession().basketId, quantity },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
  }

  async addAddress(): Promise<number> {
    const response = await this.request.post('/api/Addresss', {
      headers: this.authHeaders(),
      data: { ...ADDRESS, mobileNum: Number(ADDRESS.mobileNum) },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data.id;
  }

  async addCard(): Promise<number> {
    const response = await this.request.post('/api/Cards', {
      headers: this.authHeaders(),
      data: {
        fullName: CARD.fullName,
        cardNum: Number(CARD.cardNum),
        expMonth: Number(CARD.expMonth),
        expYear: Number(CARD.expYear),
      },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data.id;
  }

  /** Adds money to the wallet. The shop accepts a top-up only with a saved card. */
  async topUpWallet(amount: number, cardId: number): Promise<number> {
    const response = await this.request.put('/rest/wallet/balance', {
      headers: this.authHeaders(),
      data: { balance: amount, paymentId: cardId },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
    return this.walletBalance();
  }

  async walletBalance(): Promise<number> {
    const response = await this.request.get('/rest/wallet/balance', { headers: this.authHeaders() });
    expect(response.ok()).toBeTruthy();
    return (await response.json()).data;
  }

  private requireSession(): Session {
    if (!this.session) throw new Error('ShopApi: call login() first');
    return this.session;
  }

  private authHeaders(): Record<string, string> {
    return { Authorization: `Bearer ${this.requireSession().token}` };
  }
}
