import { Page } from '@playwright/test';

/** The basket as `GET /rest/basket/<id>` sends it. Only the fields that the tests read. */
export type ServerBasket = { Products: { BasketItem: { quantity: number } }[] };

/**
 * Waits for the next basket response from the server.
 * The page shows an empty basket and the counter `0` before this response arrives,
 * so a check of the basket must wait for the response first.
 */
export async function nextBasketResponse(page: Page): Promise<ServerBasket> {
  const response = await page.waitForResponse(
    (r) => /\/rest\/basket\/\d+$/.test(r.url()) && r.request().method() === 'GET',
  );
  return (await response.json()).data;
}

export function itemCount(basket: ServerBasket): number {
  return basket.Products.reduce((sum, product) => sum + product.BasketItem.quantity, 0);
}

