    this.rows = page.locator('app-basket mat-row');
    this.totalPrice = page.locator('app-basket #price');
    this.checkoutButton = page.locator('app-basket #checkoutButton');
    this.snackBar = page.locator('.mat-mdc-snack-bar-container');
    this.errorMessages = this.snackBar.and(page.locator('.errorBar'));
