import { test, expect } from './support/fixtures';
import { expectPrice } from './support/assertions';
import { APPLE_JUICE_LIMIT, PRODUCTS } from './support/test-data';

test('TC-04: Purchase limit for one product', async ({ loggedInCustomer: _, page, productList, basket, navBar }) => {
  const product = PRODUCTS.appleJuice;
  const limitMessage = `You can order only up to ${APPLE_JUICE_LIMIT} items of this product.`;

  await test.step('1. Add the product from the product list', async () => {
    await productList.open();
    await productList.addToBasket(product.name);
    await expect(productList.message(`Placed ${product.name} into basket.`).first()).toBeVisible();
    await expect(navBar.basketCounter).toHaveText('1');
  });

  await test.step(`2. Click plus until the quantity is ${APPLE_JUICE_LIMIT}`, async () => {
    await basket.open();
    for (let quantity = 2; quantity <= APPLE_JUICE_LIMIT; quantity++) {
      const update = await basket.increase(product.name);
      // The shop shows an error message only for a failed update, so an accepted update proves no message comes later.
      expect(update.ok(), `The shop accepts quantity ${quantity}`).toBeTruthy();
      await expect(basket.quantity(product.name)).toHaveText(String(quantity));
    }
    await expect(basket.quantity(product.name)).toHaveText(String(APPLE_JUICE_LIMIT));
    await expectPrice(basket.totalPrice, APPLE_JUICE_LIMIT * product.price);
    await expect(basket.errorMessages).toHaveCount(0);
  });

  await test.step('3. Click plus one more time', async () => {
    await basket.increase(product.name);
    await expect(basket.message(limitMessage).first()).toBeVisible();
  });

  await test.step('4. Read the basket', async () => {
    await expect(basket.quantity(product.name)).toHaveText(String(APPLE_JUICE_LIMIT));
    await expectPrice(basket.totalPrice, APPLE_JUICE_LIMIT * product.price);
    await expect(navBar.basketCounter).toHaveText(String(APPLE_JUICE_LIMIT));
    // The server must keep the limit too.
    await page.reload();
    await basket.waitForLoad();
    await expect(basket.quantity(product.name)).toHaveText(String(APPLE_JUICE_LIMIT));
    await expectPrice(basket.totalPrice, APPLE_JUICE_LIMIT * product.price);
  });

  await test.step('5. Add the product again from the product list', async () => {
    await productList.open();
    await productList.addToBasket(product.name);
    await expect(productList.message(limitMessage).first()).toBeVisible();
    await expect(navBar.basketCounter).toHaveText(String(APPLE_JUICE_LIMIT));
  });
});

