3	/** The basket as `GET /rest/basket/<id>` sends it. Only the fields that the tests read. */
4	export type ServerBasket = { Products: { BasketItem: { quantity: number } }[] };
5	
6	/**
7	 * Waits for the next basket response from the server.
8	 * The page shows an empty basket and the counter `0` before this response arrives,
9	 * so a check of the basket must wait for the response first.
10	 */
11	export async function nextBasketResponse(page: Page): Promise<ServerBasket> {
12	  const response = await page.waitForResponse(
13	    (r) => /\/rest\/basket\/\d+$/.test(r.url()) && r.request().method() === 'GET',
14	  );
15	  return (await response.json()).data;
16	}
17	
18	export function itemCount(basket: ServerBasket): number {
19	  return basket.Products.reduce((sum, product) => sum + product.BasketItem.quantity, 0);
20	}
