import { test } from '../../Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-q/tests/support/fixtures';
import { addSavedAddressAndCard } from '../../Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-q/tests/support/checkout';
test('TC-99 probe', async ({ page, loggedInCustomer, productList, basket, selectAddress, deliveryMethod, payment }) => {
  await addSavedAddressAndCard(loggedInCustomer);
  await productList.open();
  await productList.addToBasket('Carrot Juice (1000ml)');
  await productList.addToBasket('Apple Juice (1000ml)');
  await page.waitForTimeout(500);
  await basket.open();
  for (let i = 0; i < 5; i++) { await basket.increase('Apple Juice (1000ml)'); }
  await page.waitForTimeout(300);
  console.log('SNACK', await page.locator('.mat-mdc-snack-bar-container').evaluateAll(e => e.map(x => x.outerHTML.slice(0, 400))));
  console.log('ERRORS', await page.locator('app-basket .error, app-basket mat-error').evaluateAll(e => e.map(x => x.outerHTML)));
  await basket.checkout();
  await selectAddress.selectSavedAddressAndContinue();
  await deliveryMethod.selectAndContinue('One Day Delivery');
  await payment.selectSavedCardAndContinue();
  await page.locator('app-order-summary mat-row').first().waitFor();
  console.log('ROW', await page.locator('app-order-summary mat-row').first().evaluate(e => e.outerHTML));
});
EOF
npx playwright test /tmp/probe/probe.spec.ts --reporter=line 2>&1 | tail -30
